"""Generate the ADR-0326 reference and shared OpenAPI ProblemDetail component.

The source of truth is the production ErrorCode enum set, through error_code_catalogue.scan. CI's
--check mode compares bytes without rewriting them; regen-derived.sh owns normal regeneration.
"""

from __future__ import annotations

import argparse
import pathlib
import sys

import yaml

from error_code_catalogue import CodeRecord, scan

MARKDOWN = "docs/reference/error-codes.md"
OPENAPI = "openbank-libs/governance/error-model.openapi.yaml"
GENERATED = "<!-- GENERATED by .github/scripts/gen-error-code-catalogue.py; do not edit by hand. -->"


def _owners(records: list[CodeRecord], code: str) -> list[str]:
    return sorted({f"{record.module}.{record.enum}" for record in records if record.code == code})


def render_markdown(records: list[CodeRecord]) -> str:
    lines = [
        GENERATED,
        "",
        "# OpenBank error-code catalogue",
        "",
        "ADR-0326 stable wire codes. Codes are append-only; category, title and retryability are",
        "published semantics. Owners name the modules and enums that currently declare each code.",
        "",
        "| Code | Category | Retryable | Title | Owners |",
        "|---|---|---|---|---|",
    ]
    for code in sorted({record.code for record in records}):
        record = next(record for record in records if record.code == code)
        owners = ", ".join(_owners(records, code))
        title = record.title.replace("|", "\\|")
        lines.append(f"| `{code}` | `{record.category}` | {str(record.retryable).lower()} | {title} | {owners} |")
    return "\n".join(lines) + "\n"


def render_openapi(records: list[CodeRecord]) -> str:
    string = {"type": "string"}
    schema = {
        "type": "object",
        "additionalProperties": False,
        "required": [
            "type", "title", "status", "detail", "instance", "code", "correlationId", "retryable",
            "traceId", "message", "timestamp",
        ],
        "properties": {
            "type": string,
            "title": string,
            "status": {"type": "integer", "format": "int32"},
            "detail": string,
            "instance": string,
            "code": {"type": "string", "enum": sorted({record.code for record in records})},
            "correlationId": string,
            "retryable": {"type": "boolean"},
            "violations": {"type": "array", "items": {"$ref": "#/components/schemas/ProblemViolation"}},
            "traceId": string,
            "message": string,
            "timestamp": {"type": "string", "format": "date-time"},
            "details": {"type": "array", "items": {"$ref": "#/components/schemas/FieldError"}},
            "error": {"type": "string", "description": "Legacy compatibility member; present only on migrated legacy contracts."},
        },
    }
    document = {
        "openapi": "3.0.3",
        "info": {"title": "OpenBank shared error model", "version": "1"},
        "paths": {},
        "components": {
            "schemas": {
                "ProblemDetail": schema,
                "ProblemViolation": {
                    "type": "object",
                    "additionalProperties": False,
                    "required": ["field", "message"],
                    "properties": {"field": string, "message": string, "code": string},
                },
                "FieldError": {
                    "type": "object",
                    "additionalProperties": False,
                    "required": ["field", "message"],
                    "properties": {"field": string, "message": string},
                },
            }
        },
    }
    body = yaml.safe_dump(document, sort_keys=False, allow_unicode=True, width=120)
    return f"# GENERATED by .github/scripts/gen-error-code-catalogue.py; do not edit by hand.\n{body}"


def _outputs(records: list[CodeRecord]) -> dict[str, str]:
    return {MARKDOWN: render_markdown(records), OPENAPI: render_openapi(records)}


def write_outputs(root: pathlib.Path, records: list[CodeRecord] | None = None) -> list[pathlib.Path]:
    if records is None:
        records, _ = scan(root)
    written = []
    for relative, content in _outputs(records).items():
        target = root / relative
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(content, encoding="utf-8")
        written.append(target)
    return written


def drift(root: pathlib.Path, records: list[CodeRecord] | None = None) -> list[str]:
    if records is None:
        records, _ = scan(root)
    stale = []
    for relative, expected in _outputs(records).items():
        target = root / relative
        if not target.is_file() or target.read_text(encoding="utf-8") != expected:
            stale.append(relative)
    return stale


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--root", default=".")
    parser.add_argument("--check", action="store_true")
    parser.add_argument("--self-test", action="store_true")
    args = parser.parse_args()
    if args.self_test:
        from test_gen_error_code_catalogue import run_self_test

        return run_self_test()
    root = pathlib.Path(args.root).resolve()
    try:
        records, _ = scan(root)
        if args.check:
            stale = drift(root, records)
            for relative in stale:
                print(f"::error file={relative}::generated error catalogue is stale; run gen-error-code-catalogue.py")
            return 1 if stale else 0
        for target in write_outputs(root, records):
            print(f"WROTE {target.relative_to(root)}")
        return 0
    except (OSError, ValueError) as exc:
        print(f"::error::cannot generate error catalogue: {exc}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
